1	/** Provider/model features that affect how Keating constructs a session. */
2	export type CapabilitySupport = "native" | "adapter" | "none";
3	
4	export type RealtimeTransport = "webrtc" | "websocket" | "livekit";
5	
6	export type SearchToolKind =
7		| "openai-web-search"
8		| "google-search-grounding"
9		| "anthropic-web-search"
10		| "client-web-search";
11	
12	export type CitationKind = "provider-annotations" | "grounding-metadata" | "tool-results";
13	
14	export interface ProviderModelDescriptor {
15		provider: string;
16		id: string;
17		api?: string;
18	}
19	
20	export interface ProviderCapabilities {
21		realtimeAudio: CapabilitySupport;
22		realtimeTransports: readonly RealtimeTransport[];
23		webSearch: CapabilitySupport;
24		searchTool?: SearchToolKind;
25		toolCalls: CapabilitySupport;
26		citations: CapabilitySupport;
27		citationKind?: CitationKind;
28	}
29	
30	export interface CapabilityRule {
31		id: string;
32		provider: string | RegExp;
33		model?: RegExp;
34		api?: string | RegExp;
35		capabilities: ProviderCapabilities;
36	}
37	
38	export interface CapabilityRequest {
39		realtimeAudio?: boolean;
40		webSearch?: boolean;
41		toolCalls?: boolean;
42		citations?: boolean;
43		preferredTransports?: readonly RealtimeTransport[];
44		/** Permit Keating/client adapters when a provider has no native feature. */
45		allowAdapters?: boolean;
46	}
47	
48	export type NegotiatedRoute = "native" | "adapter" | "unavailable" | "not-requested";
49	
50	export interface CapabilityNegotiation {
51		ruleId: string;
52		model: ProviderModelDescriptor;
53		capabilities: ProviderCapabilities;
54		realtimeAudio: NegotiatedRoute;
55		transport?: RealtimeTransport;
56		webSearch: NegotiatedRoute;
57		searchTool?: SearchToolKind;
58		toolCalls: NegotiatedRoute;
59		citations: NegotiatedRoute;
60		missing: Array<"realtimeAudio" | "webSearch" | "toolCalls" | "citations" | "transport">;
61		usesFallback: boolean;
62	}
63	
