7		type LiveSpeechState,
8		type SpeechProvider,
9		type SpeechSynthesisRequest,
10		type SpeechSynthesisResult,
11	} from "../speech";
12	import { withApiRetry } from "../api-retry";
13	
14	const GEMINI_VOICES = ["Kore", "Puck", "Charon", "Fenrir", "Leda", "Orus", "Aoede"];
15	
16	function contentParts(message: any): any[] {
17		return Array.isArray(message?.serverContent?.modelTurn?.parts)
18			? message.serverContent.modelTurn.parts
19			: [];
20	}
21	
22	async function synthesize(request: SpeechSynthesisRequest): Promise<SpeechSynthesisResult> {
23		const { utterance, settings, getApiKey, signal } = request;
24		const apiKey = await getApiKey("google");
25		if (!apiKey) {
26			throw new Error("No Google API key configured. Sign in to Google in Settings → Providers & Models.");
27		}
28	
29		const { GoogleGenAI, Modality, ThinkingLevel } = await import("@google/genai");
30		const ai = new GoogleGenAI({ apiKey });
31	
32		let session: { sendRealtimeInput: (params: { text: string }) => void; close: () => void } | null = null;
33		let done = false;
34		let audioChunks = 0;
35		let playedChunks = 0;
36		let transcript = "";
37	
38		const finish = (resolve: (value: SpeechSynthesisResult) => void) => {
39			if (done) return;
40			done = true;
41			session?.close();
42			resolve({ audioChunks, playedChunks, transcript: transcript.trim() });
43		};
44	
45		return await new Promise<SpeechSynthesisResult>((resolve, reject) => {
46			const timeout: ReturnType<typeof setTimeout> = setTimeout(() => {
47				if (done) return;
48				done = true;
49				session?.close();
50				reject(new Error("Gemini Live speech timed out."));
51			}, 30_000);
52	
53			const abort = () => {
54				if (done) return;
55				done = true;
56				clearTimeout(timeout);
57				session?.close();
58				reject(new Error("Gemini Live speech aborted."));
59			};
60	
61			if (signal?.aborted) {
62				abort();
63				return;
64			}
65			signal?.addEventListener("abort", abort, { once: true });
66	
67			withApiRetry(() => ai.live
68				.connect({
69					model: settings.model || GEMINI_LIVE_SPEECH_MODEL,
70					callbacks: {
71						onmessage: (message: any) => {
72							for (const part of contentParts(message)) {
73								const data = part.inlineData?.data;
74								if (typeof data === "string" && data.length > 0) {
75									audioChunks += 1;
76									if (schedulePcmAudio(data)) playedChunks += 1;
77								}
78								if (typeof part.text === "string") transcript += part.text;
79							}
80	
81							const outputText = message?.serverContent?.outputTranscription?.text;
82							if (typeof outputText === "string") transcript += outputText;
83	
84							if (message?.serverContent?.turnComplete || message?.serverContent?.generationComplete) {
85								clearTimeout(timeout);
86								signal?.removeEventListener("abort", abort);
87								finish(resolve);
88							}
89						},
90						onerror: (event: ErrorEvent) => {
91							if (done) return;
92							done = true;
93							clearTimeout(timeout);
94							signal?.removeEventListener("abort", abort);
95							reject(new Error(event.message || "Gemini Live speech failed."));
96						},
97						onclose: () => {
98							if (done) return;
99							clearTimeout(timeout);
100							signal?.removeEventListener("abort", abort);
101							finish(resolve);
102						},
103					},
104					config: {
105						responseModalities: [Modality.AUDIO],
106						outputAudioTranscription: {},
107						speechConfig: {
108							voiceConfig: {
109								prebuiltVoiceConfig: { voiceName: utterance.voice },
110							},
111						},
112						systemInstruction:
113							"You are Keating's voice layer. Speak the provided learner-facing line only. Keep it natural, concise, and conversational. Do not add extra teaching content.",
114						thinkingConfig: { thinkingLevel: ThinkingLevel.MINIMAL },
115					},
