182	async function mintEphemeralKey(apiKey: string, model: string, voice: string, signal?: AbortSignal): Promise<string> {
183		const response = await withApiRetry(async () => {
184			const result = await fetch("https://api.openai.com/v1/realtime/client_secrets", {
185				method: "POST",
186				headers: {
187					"Content-Type": "application/json",
188					Authorization: `Bearer ${apiKey}`,
189				},
190				body: JSON.stringify({
191					session: {
192						type: "realtime",
193						model,
194						audio: {
195							output: { voice },
196						},
197					},
198				}),
199				signal,
200			});
201			if (!result.ok) {
202				const errText = await result.text().catch(() => "");
203				const retryAfter = result.headers.get("retry-after");
204				throw new Error(`Realtime session mint failed (${result.status}): ${errText.slice(0, 200) || result.statusText}${retryAfter ? ` retry-after: ${retryAfter}` : ""}`);
205			}
206			return result;
207		}, { signal });
208		const data = (await response.json()) as { value?: string; client_secret?: { value?: string } };
209		const value = data.value ?? data.client_secret?.value;
210		if (!value) throw new Error("Realtime session mint returned no ephemeral secret value");
